import { query } from '../client.js';
export const sprintHelp = [
  'crew sprint list --project ID [--status planned|active|completed] [--limit N] [--cursor CURSOR]',
  'crew sprint create --project ID --name NAME --start YYYY-MM-DD --end YYYY-MM-DD [--goal TEXT]',
  'crew sprint show ID | scope ID | burndown ID',
  'crew sprint update ID [--name NAME] [--goal TEXT] [--start DATE] [--end DATE]',
  'crew sprint add ID --issues ISSUE,ISSUE | remove ID --issue ISSUE',
  'crew sprint start ID | complete ID [--carry-over NEXT_SPRINT] | delete ID --yes',
  'scope-page ID | candidates ID | carry-targets ID accept --q TEXT --limit N --cursor CURSOR. Mutations accept --revision HEX.',
  'Only one sprint is active per project. Completed history is immutable. Carry-over targets a planned sprint.'
].join('\n');
function required(value, option) {
  if (!value || value === true) throw new Error('Provide --' + option);
  return value;
}
export async function sprintCommand({ args, options, client, print }) {
  const [action = 'list', id] = args;
  if (action === 'help') return print(sprintHelp);
  if (action === 'list') return print(await client.get('/projects/' + encodeURIComponent(required(options.project, 'project')) + '/sprints' + query({ status: options.status, q: options.q, limit: options.limit, cursor: options.cursor })));
  if (action === 'create') return print(await client.post('/projects/' + encodeURIComponent(required(options.project, 'project')) + '/sprints', {
    name: required(options.name, 'name'), goal: options.goal ?? '', startDate: required(options.start, 'start'), endDate: required(options.end, 'end')
  }));
  if (!id) throw new Error('Provide a sprint ID. ' + sprintHelp);
  const path = '/sprints/' + encodeURIComponent(id);
  if (action === 'show' || action === 'scope') return print(await client.get(path + (options.history ? '?history=true' : '')));
  if (['scope-page', 'candidates', 'carry-targets'].includes(action)) return print(await client.get(path + '/' + (action === 'scope-page' ? 'scope' : action) + query({ q: options.q, limit: options.limit, cursor: options.cursor, history: options.history })));
  const revision = options.revision ? { expectedRevision: options.revision } : {};
  if (action === 'burndown') return print(await client.get(path + '/burndown'));
  if (action === 'update') {
    const body = {};
    for (const name of ['name', 'goal']) if (options[name] !== undefined) body[name] = options[name];
    if (options.start !== undefined) body.startDate = options.start;
    if (options.end !== undefined) body.endDate = options.end;
    return print(await client.patch(path, { ...body, ...revision }));
  }
  if (action === 'start') return print(await client.post(path + '/start', revision));
  if (action === 'complete') return print(await client.post(path + '/complete', { ...revision, ...(options['carry-over'] ? { carryOverSprintId: options['carry-over'] } : {}) }));
  if (action === 'add') return print(await client.post(path + '/issues', { ...revision, issueIds: required(options.issues, 'issues').split(',').map(value => value.trim()).filter(Boolean) }));
  if (action === 'remove') return print(await client.delete(path + '/issues/' + encodeURIComponent(required(options.issue, 'issue')), revision));
  if (action === 'delete') {
    if (!options.yes) throw new Error('Sprint deletion requires --yes');
    return print(await client.delete(path, revision));
  }
  throw new Error('Unknown sprint action: ' + action + '. Use crew sprint help');
}
